script:
(function () {
  'use strict';
  // Fixed-term loan vs a line of credit for the same amount, drawn in full today.
  //   Loan: level payment P = A x i / (1 - (1 + i)^-n), i = APR / 12 (P = A / n at 0%), with the
  //     last payment trimmed to what is owed.
  //   Line: each month interest = balance x APR / 12 (rounded to the cent), then the payment is
  //     interest only, or interest + p% of the month's starting balance but at least the
  //     lender's lowest payment, or a fixed amount - always capped at what is owed.
  //   "Line still owed when the loan is paid off" is the line balance after the loan's term.
  //   Interest-only (or a payment that does not cover the interest) never clears the line.
  // Verified (scratchpad b6credit/lc.test.js): $20,000 at 9% over 48 months -> $497.70
  //   (published amortization tables) and $3,889.61 of interest; line at 9%, interest + 1%
  //   with a $50 floor -> first payment $350.00 ($150 interest + $200), interest-only ->
  //   $150.00 a month and $20,000 still owed; a fixed $497.71 (the suggested payment, rounded up) on a
  //   9% line clears it in 48 months like the loan; at 0% the loan payment is A / n; total paid = amount +
  //   interest for every option.

  // ---- Calculation ----
  var MAX_MONTHS = 1200;
  function cents(x) { return Math.round(x * 100) / 100; }

  function loanPayment(amount, apr, months) {
    var i = apr / 12;
    if (i === 0) return amount / months;
    return amount * i / (1 - Math.pow(1 + i, -months));
  }

  // Returns month-by-month rows [{ pay, interest, balance }] until cleared or MAX_MONTHS.
  function schedule(amount, apr, payFn) {
    var bal = amount, rows = [];
    for (var m = 1; m <= MAX_MONTHS && bal > 0.005; m++) {
      var interest = cents(bal * apr / 12);
      var pay = Math.min(cents(payFn(bal, interest, m)), cents(bal + interest));
      bal = cents(bal + interest - pay);
      if (bal < 0.005) bal = 0;
      rows.push({ pay: pay, interest: interest, balance: bal });
    }
    return rows;
  }

  function loanSchedule(amount, apr, months) {
    var P = loanPayment(amount, apr, months);
    return schedule(amount, apr, function (bal, interest, m) { return m >= months ? bal + interest : P; });
  }

  function lineSchedule(amount, apr, option, floor, fixed) {
    return schedule(amount, apr, function (bal, interest) {
      if (option === 'fixed') return fixed;
      if (option === 0) return interest;
      return Math.max(interest + option * bal, floor);
    });
  }

  function summarize(rows, upTo) {
    var paid = 0, interest = 0, n = Math.min(upTo, rows.length);
    for (var k = 0; k < n; k++) { paid += rows[k].pay; interest += rows[k].interest; }
    return { paid: paid, interest: interest, balance: n ? rows[n - 1].balance : 0 };
  }

  // ---- UI ----
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells, firstIsHeader) {
    var tr = document.createElement('tr');
    cells.forEach(function (t, k) {
      var c = document.createElement(firstIsHeader && k === 0 ? 'th' : 'td');
      if (firstIsHeader && k === 0) c.setAttribute('scope', 'row');
      c.textContent = t; tr.appendChild(c);
    });
    body.appendChild(tr);
  }
  function clearedAt(rows) {
    return rows.length && rows[rows.length - 1].balance === 0 ? rows.length : 0;
  }

  function clearResults() {
    ['lcpLoanPay', 'lcpLinePay', 'lcpLineLeft', 'lcpLineTime'].forEach(function (id) { set(id, '–'); });
    ['lcpLoanNote', 'lcpLinePayNote', 'lcpLineTimeNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('lcpTip').hidden = true;
    clearBody('lcpCompare'); clearBody('lcpYears');
  }

  function update() {
    var optRaw = document.getElementById('lcpOption').value;
    var option = optRaw === 'fixed' ? 'fixed' : parseFloat(optRaw);
    document.getElementById('lcpFixedWrap').hidden = option !== 'fixed';
    document.getElementById('lcpFloorWrap').hidden = option === 'fixed' || option === 0;
    var amount = num('lcpAmount'), loanRate = num('lcpLoanRate'), term = Math.round(num('lcpTerm')),
        lineRate = num('lcpLineRate'), floor = num('lcpFloor'), fixed = num('lcpFixed');
    if (option !== 'fixed' && option !== 0 && document.getElementById('lcpFloor').value.trim() === '') floor = 0;
    var error = document.getElementById('lcpError'), problem = '';
    if (isNaN(amount) || amount <= 0 || amount > 1e8) problem = 'Enter an amount above $0.';
    else if (isNaN(loanRate) || loanRate < 0 || loanRate > 100 || isNaN(lineRate) || lineRate < 0 || lineRate > 100) problem = 'Enter APRs from 0 to 100%.';
    else if (isNaN(term) || term < 1 || term > 360) problem = 'Enter a loan term from 1 to 360 months.';
    else if (option === 'fixed' && (isNaN(fixed) || fixed <= 0)) problem = 'Enter a fixed monthly payment above $0.';
    else if (option !== 'fixed' && option !== 0 && (isNaN(floor) || floor < 0)) problem = 'Enter a lowest payment of $0 or more.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var loan = loanSchedule(amount, loanRate / 100, term);
    var line = lineSchedule(amount, lineRate / 100, option, floor, fixed);
    var loanAll = summarize(loan, loan.length), lineTerm = summarize(line, term), lineAll = summarize(line, line.length);
    var lineDone = clearedAt(line);

    set('lcpLoanPay', money.format(loan[0].pay) + '/mo');
    set('lcpLoanNote', 'Fixed for ' + duration(term) + '.');
    set('lcpLinePay', money.format(line[0].pay) + '/mo');
    var lastLinePay = line[Math.min(term, line.length) - 1].pay;
    set('lcpLinePayNote', option === 'fixed' ? 'The same each month.' :
      (option === 0 ? 'Interest only: the balance never goes down.' : 'Falls to ' + money.format(lastLinePay) + ' by month ' + Math.min(term, line.length) + ' as the balance shrinks.'));
    set('lcpLineLeft', money.format(lineTerm.balance));
    set('lcpLineTime', lineDone ? duration(lineDone) : 'Never');
    set('lcpLineTimeNote', lineDone ? 'Total interest ' + money.format(lineAll.interest) + '.' : (line[line.length - 1].balance > amount + 0.005 ? 'This payment does not cover the interest, so the balance keeps growing.' : 'This payment never reduces the balance. You would still owe ' + money.format(amount) + '.'));

    var body = clearBody('lcpCompare');
    addRow(body, ['Monthly payment', money.format(loan[0].pay), option === 'fixed' || option === 0 ? money.format(line[0].pay) : money.format(line[0].pay) + ' falling'], true);
    addRow(body, ['Paid in the first ' + duration(term), money.format(loanAll.paid), money.format(lineTerm.paid)], true);
    addRow(body, ['Interest in the first ' + duration(term), money.format(loanAll.interest), money.format(lineTerm.interest)], true);
    addRow(body, ['Still owed after ' + duration(term), money.format(0), money.format(lineTerm.balance)], true);
    addRow(body, ['Time to pay off', duration(loan.length), lineDone ? duration(lineDone) : 'Never'], true);
    addRow(body, ['Total interest to pay off', money.format(loanAll.interest), lineDone ? money.format(lineAll.interest) : 'Keeps growing'], true);

    var tip = document.getElementById('lcpTip');
    var clearPay = loanPayment(amount, lineRate / 100, term);
    tip.hidden = false;
    tip.textContent = 'To clear the credit line in the same ' + duration(term) + ', pay at least ' + money.format(Math.ceil(clearPay * 100) / 100) +
      ' a month on it. A lower required payment eases your budget now but leaves the balance, and the interest, running for longer.';

    var years = clearBody('lcpYears');
    var horizon = Math.min(360, Math.max(loan.length, lineDone || 360));
    for (var y = 1; y * 12 - 11 <= horizon; y++) {
      var from = (y - 1) * 12, to = Math.min(y * 12, horizon);
      var lp = 0, li = 0, kp = 0;
      for (var k = from; k < to; k++) {
        if (k < loan.length) kp += loan[k].pay;
        if (k < line.length) { lp += line[k].pay; li += line[k].interest; }
      }
      var loanBal = to <= loan.length ? loan[to - 1].balance : 0;
      var lineBal = to <= line.length ? line[to - 1].balance : 0;
      addRow(years, [String(y), money.format(kp), money.format(loanBal), money.format(lp), money.format(li), money.format(lineBal)]);
      if (loanBal === 0 && lineBal === 0) break;
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('lcpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
